<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/levellist')}" >等级管理</a>										<if condition="$config.open_recharge_level eq 1">					<a href="{pigcms{:U('User/recharge_level')}" class="on">充值获得等级</a>					</if>										<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('User/add_recharge_level')}','添加充值等级配置',650,500,true,false,false,addbtn,'add',true);" style="margin-left:20px;">添加充值等级配置</a>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>												<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th width="50px">ID</th>								<th >等级名称</th>								<th >等级级别</th>								<th >充值金额</th>								<th >状态</th>																<th>操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$level[$vo['level']]}</td>										<td>{pigcms{$vo.level}</td>										<td>{pigcms{$vo.money|floatval}</td>										<td><if condition="$vo.status eq 1"><font color="green">正常</font><else /><font color="red">禁用</font></if></td>																				<td><a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('User/add_recharge_level',array('id'=>$vo['id']))}','编辑等级信息',650,500,true,false,false,editbtn,'edit',true);">编 辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo['id']}" url="/admin.php?g=System&c=User&a=del_recharge_level">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="6">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="6">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>